const rows = Array.isArray($json.list) ? $json.list : [];
const draftOnly = true;
const blockedStatuses = new Set(['unsubscribed', 'bounced', 'complained']);
const textFields = ['company_homepage_name', 'parent_company', 'best_url', 'canonical_domain', 'website_content', 'source_urls', 'selected_contact_name', 'selected_contact_title', 'selected_contact_role', 'selected_contact_email', 'selected_contact_linkedin_url', 'validated_email', 'unsubscribe_status', 'email_source'];
const output = [];
for (const row of rows) {
  const normalized = { ...row };
  for (const field of textFields) normalized[field] = String(normalized[field] || '').trim();
  normalized.unsubscribe_status = normalized.unsubscribe_status || 'active';
  normalized.do_not_contact = normalized.do_not_contact === true || String(normalized.do_not_contact).toLowerCase() === 'true';
  const unsub = normalized.unsubscribe_status.toLowerCase();
  const hasEmail = Boolean(String(normalized.selected_contact_email || normalized.validated_email || '').trim());
  if (normalized.do_not_contact) continue;
  if (blockedStatuses.has(unsub)) continue;
  if (!hasEmail && !draftOnly) continue;
  output.push({ json: { ...normalized, draft_only: draftOnly } });
}
return output;

const output = [];
for (const [index, item] of items.entries()) {
  const plan = item.json || {};
  if (!plan.patch || !plan.record) {
    output.push({ json: { ...plan, skip_llm: true } });
    continue;
  }
  const sourceRow = $('Rows To Items').all()[index]?.json || {};
  const record = plan.record || {};
  const classification = record.classification || {};
  const funding = record.funding || {};
  const row = {
    ...sourceRow,
    Id: plan.patch.Id,
    company_name: sourceRow.company_name || plan.patch.company_name || classification.company_name || '',
    selected_contact_name: sourceRow.selected_contact_name || plan.patch.selected_contact_name || '',
    selected_contact_title: sourceRow.selected_contact_title || plan.patch.selected_contact_title || '',
  };
  const system = 'You write short, evidence-based cold email drafts for RAYN Secure. Return strict JSON only. Do not send emails. Do not invent facts.';
  const user = {
    company_name: row.company_name || plan.row_id || '',
    selected_contact_title: row.selected_contact_title || '',
    entity_type_guess: classification.entity_type_guess,
    pressure_type: classification.pressure_type,
    outreach_variant: plan.patch.outreach_variant,
    outreach_trigger_signal: classification.outreach_trigger_signal,
    data_type_signal: classification.data_type_signal,
    problem_area: classification.problem_area,
    problem_hypothesis: classification.problem_hypothesis,
    value_asset_offer: classification.value_asset_offer,
    recommended_first_cert: classification.recommended_first_cert,
    hia_relevant: classification.hia_relevant,
    hia_timeline_batch_guess: classification.hia_timeline_batch_guess,
    hia_deadline_claim_safe: classification.hia_deadline_claim_safe,
    pdpa_relevant: classification.pdpa_relevant,
    funding_status: funding.funding_status,
    primary_funding_program: funding.primary_funding_program,
    funding_claim_line: funding.funding_claim_line,
    funding_cta_asset: funding.funding_cta_asset,
    funding_confidence: funding.funding_confidence,
    rules: [
      'Email 1 leads with pressure_type, not RAYN services.',
      'Email 2 is a diagnostic tied to the same pressure.',
      'Email 3 is funding-only and must use funding_claim_line verbatim.',
      'Email 4 closes the loop.',
      'Do not say if you are an SME or if you are an NPO.',
      'Do not say eligible SMEs and NPOs may.',
      'Do not claim guaranteed funding.',
      'Do not say Cyber Essentials makes the company PDPA compliant.',
      'Do not say Cyber Essentials completes HIA compliance.',
      'Keep Email 1 <= 85 words, Email 2 <= 80, Email 3 <= 95, Email 4 <= 55.',
      'Use one tiny CTA per email.'
    ],
    return_shape: {
      email_1: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_2: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_3: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      email_4: { subject_options: [], chosen_subject: '', body: '', word_count: 0 },
      evidence_used: [],
      claims_avoided: [],
      quality_notes: []
    }
  };
  output.push({
    json: {
      row: row,
      planner_result: plan,
      body: {
        model: 'anthropic/claude-sonnet-4.6',
        temperature: 0.2,
        max_tokens: 1800,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: JSON.stringify(user) }
        ],
        response_format: { type: 'json_object' }
      }
    }
  });
}
return output;

const output = [];
for (let index = 0; index < items.length; index++) {
  const response = items[index].json || {};
  const prepared = $('Prepare OpenRouter Email Draft').all()[index]?.json || {};
  output.push({ json: { ...prepared, openrouter_response: response } });
}
return output;

function wordCount(text) {
  return String(text || '').match(/\b[\w'-]+\b/g)?.length || 0;
}
function ensureFundingClaim(patch) {
  if (patch.pressure_type === 'not_ready') return patch;
  const claim = String(patch.funding_claim_line || '').trim();
  if (!claim) return patch;
  const body = String(patch.email_3_body || '');
  if (body.includes(claim)) return patch;
  const replacement = ['Hi,', '', claim, '', 'This is subject to programme confirmation.', '', 'Should I send the route summary?', '', 'Best,', 'SK', 'RAYN Secure'].join('\n');
  let flags = [];
  try { flags = JSON.parse(patch.email_quality_flags || '[]'); } catch (error) { flags = []; }
  flags = flags.filter((flag) => flag !== 'email_3_missing_funding_claim_line');
  let sequenceJson = patch.email_sequence_json;
  try {
    const sequence = JSON.parse(patch.email_sequence_json || '{}');
    if (sequence.email_3) {
      sequence.email_3.body = replacement;
      sequence.email_3.word_count = wordCount(replacement);
      sequenceJson = JSON.stringify(sequence);
    }
  } catch (error) {}
  return { ...patch, email_3_body: replacement, email_sequence_json: sequenceJson, email_quality_flags: JSON.stringify(flags) };
}
const patches = [];
const errors = [];
for (const item of items) {
  const body = item.json || {};
  if (body.patch && body.patch.Id) {
    patches.push(ensureFundingClaim(body.patch));
  } else {
    errors.push({ row_id: body.row_id || '', error: body.error || 'missing_patch' });
  }
}
return [{ json: { patches, errors, count: patches.length } }];
